def fill_matrix(n, k):
    if k > n * n / 2:
        return -1

    matrix = [[0] * n for _ in range(n)]
    row, col = 0, 0

    while k > 0:
        if row == col:
            matrix[row][col] = 1
            k -= 1
        row += 1
        if row == n:
            row = col + 1
            col += 1

    return matrix

def main():
    n, k = map(int, input().split())
    result = fill_matrix(n, k)
    if result == -1:
        print(-1)
    else:
        for row in result:
            print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
